mapper.select:
SELECT i.id, i.job_id, j.job_name, i.enterprise_id, e.enterprise_name, i.interview_status, CASE i.interview_status WHEN 0 THEN '待安排' WHEN 1 THEN '已安排' WHEN 2 THEN '已完成' WHEN 3 THEN '已取消' ELSE '未知' END AS interview_status_name, i.interview_time, i.interview_location, i.interview_type, i.remark, i.create_time FROM interview i LEFT JOIN job j ON i.job_id = j.id LEFT JOIN enterprise e ON i.enterprise_id = e.id WHERE i.student_id = #{studentId}
AND i.interview_status = #{status}
ORDER BY i.create_time DESC
